CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY);
CREATE TABLE users(id text PRIMARY KEY, username text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL DEFAULT '', oidc_issuer text, oidc_subject text, groups text[] NOT NULL DEFAULT '{}', groups_expires_at timestamptz, disabled boolean NOT NULL DEFAULT false, root boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(oidc_issuer,oidc_subject));
CREATE UNIQUE INDEX one_root ON users(root) WHERE root;
CREATE TABLE applications(id text PRIMARY KEY, name text NOT NULL, from_address text NOT NULL, reply_to text NOT NULL DEFAULT '', daily_limit integer NOT NULL DEFAULT 1000 CHECK(daily_limit>0), rate_per_minute integer NOT NULL DEFAULT 60 CHECK(rate_per_minute>0), recipient_hour_limit integer NOT NULL DEFAULT 5 CHECK(recipient_hour_limit>0), queue_limit integer NOT NULL DEFAULT 5000 CHECK(queue_limit>0), paused boolean NOT NULL DEFAULT false, next_send_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bindings(user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, scope text NOT NULL, role text NOT NULL, PRIMARY KEY(user_id,scope,role));
CREATE TABLE group_mappings(group_slug text NOT NULL, scope text NOT NULL, role text NOT NULL, PRIMARY KEY(group_slug,scope,role));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, method text NOT NULL, csrf text NOT NULL, access_token text NOT NULL DEFAULT '', refresh_token text NOT NULL DEFAULT '', token_expiry timestamptz, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_attempts(bucket text PRIMARY KEY, attempts integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE oauth_states(state_hash text PRIMARY KEY, verifier text NOT NULL, nonce text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE api_keys(id text PRIMARY KEY, application_id text NOT NULL REFERENCES applications(id), name text NOT NULL, token_hash text UNIQUE NOT NULL, scopes text[] NOT NULL, revoked boolean NOT NULL DEFAULT false, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE templates(id text PRIMARY KEY, application_id text NOT NULL REFERENCES applications(id), slug text NOT NULL, name text NOT NULL, current_version integer NOT NULL DEFAULT 1, UNIQUE(application_id,slug));
CREATE TABLE template_versions(template_id text NOT NULL REFERENCES templates(id), version integer NOT NULL, subject text NOT NULL, html text NOT NULL, plain text NOT NULL, variables text[] NOT NULL DEFAULT '{}', project jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(template_id,version));
CREATE TABLE campaigns(id text PRIMARY KEY, application_id text NOT NULL REFERENCES applications(id), name text NOT NULL, state text NOT NULL DEFAULT 'draft', source_rows jsonb NOT NULL DEFAULT '[]', approved_by text REFERENCES users(id), approved_at timestamptz, scheduled_at timestamptz, created_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_rows(id text PRIMARY KEY, campaign_id text NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE, ordinal integer NOT NULL, recipient text NOT NULL, template_id text REFERENCES templates(id), template_version integer, variables jsonb NOT NULL DEFAULT '{}', errors text[] NOT NULL DEFAULT '{}', excluded boolean NOT NULL DEFAULT false, dispatch_key text NOT NULL, UNIQUE(campaign_id,ordinal));
CREATE TABLE messages(id text PRIMARY KEY, application_id text NOT NULL REFERENCES applications(id), campaign_id text REFERENCES campaigns(id), recipient text NOT NULL, from_address text NOT NULL, reply_to text NOT NULL DEFAULT '', subject text NOT NULL, html text NOT NULL, plain text NOT NULL, class text NOT NULL CHECK(class IN ('transactional','otp','bulk')), status text NOT NULL DEFAULT 'queued', idempotency_key text NOT NULL, payload_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, lease_until timestamptz, lease_token text, last_error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), relay_accepted_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id,idempotency_key));
CREATE INDEX message_queue ON messages(available_at,created_at) WHERE status IN ('queued','retry_wait');
CREATE INDEX message_app_created ON messages(application_id,created_at);
CREATE INDEX message_recipient ON messages(application_id,recipient,created_at);
CREATE TABLE delivery_events(id bigserial PRIMARY KEY, message_id text NOT NULL REFERENCES messages(id) ON DELETE CASCADE, status text NOT NULL, detail text NOT NULL DEFAULT '', event_key text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platform_settings(id integer PRIMARY KEY CHECK(id=1), paused boolean NOT NULL DEFAULT false, rate_per_minute integer NOT NULL DEFAULT 120 CHECK(rate_per_minute>0), max_connections integer NOT NULL DEFAULT 2 CHECK(max_connections>0), next_send_at timestamptz NOT NULL DEFAULT now(), dispatch_counter bigint NOT NULL DEFAULT 0, circuit_until timestamptz, consecutive_failures integer NOT NULL DEFAULT 0);
INSERT INTO platform_settings(id) VALUES(1);
CREATE TABLE audit_logs(id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, scope text NOT NULL DEFAULT '', detail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES(1);
